// A source/shape repair is a new objective. Keep its complete saved physical
// prefix and raw nuisance columns without replaying obsolete shape patches.
template<class Pin> inline eventio::Json restore_joint_native_repair_v1(JointALBuilder&b,const eventio::Json&cfg,const eventio::Json&manifest,const eventio::Json&previous_cfg,const std::string&model_file,const std::string&packet_file,const std::filesystem::path&out,Pin pin){
 using Json=eventio::Json;auto need=[](bool x,const std::string&w){if(!x)throw std::runtime_error("native repair restart: "+w);};
 need(cfg.contains("dense_source_qualification")&&cfg.at("source_uv_capture_objective")==previous_cfg.at("source_uv_capture_objective")&&cfg.at("gpu_raw_uv")==previous_cfg.at("gpu_raw_uv"),"same observed measurement operator and GPU mathematics required");
 const auto input=pin(manifest.at("input_model"));need(eventio::file_sha256(model_file)==manifest.at("input_model").at("sha256")&&eventio::file_sha256(packet_file)==manifest.at("source_packet").at("sha256"),"current model and complete source packet identity");
 const auto saved=eventio::read_json(pin(manifest.at("model"))),current=eventio::read_json(input);const auto&old_blocks=saved.at("blocks");need(current.at("blocks").size()>=old_blocks.size()&&b.core.model.blocks.size()==current.at("blocks").size(),"complete physical prefix missing");
 for(std::size_t i=0;i<old_blocks.size();++i){const auto& a=old_blocks.at(i);const auto& c=current.at("blocks").at(i);auto& live=b.core.model.blocks.at(i);need(a.at("name")==c.at("name")&&a.at("values")==c.at("values")&&a.at("lower")==c.at("lower")&&a.at("upper")==c.at("upper")&&a.at("scales")==c.at("scales")&&live.name==a.at("name")&&live.values==a.at("values").get<std::vector<double>>(),"physical prefix values/domain changed at "+std::to_string(i));}
 const auto&proof=manifest.at("native_print_repair");need(proof.at("model")==manifest.at("input_model")&&proof.at("parent_model")==manifest.at("model")&&proof.at("source_pixels_changed")==false&&proof.at("original_physical_values_preserved")==true,"explicit source/shape repair provenance");for(const auto&r:proof.at("source_evidence"))pin(r);
 const auto prior=JointPacket::load(pin(manifest.at("producer_source_packet")).string(),b.core.model);const std::size_t old=prior.rows.size(),n=b.core.packet.rows.size();need(n>old,"full source append missing");std::size_t restored=0,withheld=0;
 for(std::size_t i=0;i<old;++i){const auto&a=prior.rows[i];const auto&c=b.core.packet.rows[i];need(a.source_row_id==c.source_row_id&&a.source_dataset_id==c.source_dataset_id&&a.shot_id==c.shot_id&&a.pts==c.pts&&a.uv==c.uv&&a.material==c.material&&a.kind==c.kind&&a.E==c.E&&a.normal==c.normal&&a.width_block==c.width_block&&a.width_sign==c.width_sign&&bool(a.query)==bool(c.query),"original source measurement changed at "+std::to_string(i));if(a.query)need(a.query->alpha==c.query->alpha&&a.query->uv==c.query->uv&&a.query->nx==c.query->nx&&a.query->ny==c.query->ny&&a.query->den==c.query->den&&a.query->origin==c.query->origin&&a.query->scale==c.query->scale,"original finite source query changed");restored+=!a.active&&c.active;withheld+=a.active&&!c.active;}
 const auto binding=eventio::read_json(pin(manifest.at("state_binding")));const auto nuisance=eventio::read_json(pin(manifest.at("nuisance_manifest")));need(binding.at("state_token")==manifest.at("expected_state_token")&&binding.at("source_packet_sha256")==manifest.at("producer_source_packet").at("sha256")&&binding.at("true_RS_verified")==false&&nuisance.at("raw_rows")==old&&nuisance.at("packet_sha256")==manifest.at("producer_source_packet").at("sha256"),"saved state identity and denominator");
 std::ifstream stream(pin(manifest.at("checkpoint")));auto cp=read_checkpoint(stream);need(cp.state.token()==manifest.at("expected_state_token")&&cp.state.data().identity.objective_id==manifest.at("objective_id")&&cp.outer.lambda.empty()&&cp.outer.nu.empty()&&cp.outer.rho==0,"saved complete observed state token");const auto&params=cp.state.data().parameters;need(params.size()>=old_blocks.size(),"physical checkpoint prefix");
 for(std::size_t i=0;i<old_blocks.size();++i)need(params[i].name==b.core.model.blocks[i].name&&params[i].values==b.core.model.blocks[i].values,"checkpoint/model physical values disagree");
 std::vector<double> stations,rows,alphas;std::vector<std::uint32_t> paths;
 for(const char*filename:{"station.f64","row.f64","alpha.f64","path.u32"}){const auto&r=manifest.at("files").at(filename);const auto bytes=eventio::bytes(pin(r));const bool is_path=std::string(filename)=="path.u32";need(r.at("sha256")==nuisance.at("files").at(filename).at("sha256")&&bytes.size()==old*(is_path?4:8),"raw saved auxiliary bytes");if(is_path){paths.resize(old);std::memcpy(paths.data(),bytes.data(),bytes.size());}else{auto&v=std::string(filename)=="station.f64"?stations:std::string(filename)=="row.f64"?rows:alphas;v.resize(old);std::memcpy(v.data(),bytes.data(),bytes.size());for(double z:v)need(std::isfinite(z),"nonfinite saved auxiliary");}}
 need(cp.state.data().discrete.at("finite_material_paths_RLE_u32_v1")==joint_path_RLE(paths),"saved path column differs from complete checkpoint");
 for(std::size_t k=old_blocks.size();k<params.size();++k){const auto&p=params[k];const auto slash=p.name.find('/');const auto family=p.name.substr(0,slash);if(family=="station"||family=="row"||family=="alpha"){const auto i=std::stoull(p.name.substr(slash+1));need(i<old&&p.values.size()==1,"saved nuisance identity");const auto&v=family=="station"?stations:family=="row"?rows:alphas;need(std::memcmp(p.values.data(),&v[i],8)==0,"saved nuisance binary64 mismatch");}}
 std::vector<bool> changed_material(saved.at("materials").size());for(std::size_t mi=0;mi<changed_material.size();++mi)changed_material[mi]=current.at("materials").at(mi)!=saved.at("materials").at(mi);
 std::size_t changed_shape_rows=0;for(std::size_t i=0;i<old;++i){auto&r=b.core.packet.rows[i];const auto&ma=b.core.model.materials.at(r.material);need(paths[i]<ma.paths.size(),"historical path lost in native shape repair");b.core.station[i]=stations[i];b.core.row[i]=rows[i];b.core.alpha[i]=alphas[i];r.path=int(paths[i]);r.row=rows[i];r.alpha=alphas[i];if(changed_material.at(r.material))++changed_shape_rows;}
 auto extras=b.restore_native_repair_extras_v1(cp.state);
 const auto nav_file=pin(manifest.at("print_numeric_navigation"));const auto nav=eventio::read_json(nav_file);need(nav.at("schema")=="rinkfit.repaired_print_numeric_navigation.v1"&&nav.at("model")==manifest.at("input_model")&&nav.at("source_packet")==manifest.at("source_packet")&&nav.at("source_UV_ID_PTS_membership_changed")==false&&nav.at("initialization_only")==true,"numeric print navigation provenance");pin(nav.at("issuer"));pin(nav.at("reused_initializer"));for(const auto&c:nav.at("columns").items())pin(c.value());
 const auto nr=eventio::read_array<std::uint64_t>(nav_file.parent_path(),nav.at("columns").at("row_index"),"<u8");const auto ns=eventio::read_array<double>(nav_file.parent_path(),nav.at("columns").at("station"),"<f8");const auto npath=eventio::read_array<std::uint32_t>(nav_file.parent_path(),nav.at("columns").at("path"),"<u4");need(nr.size()==ns.size()&&nr.size()==npath.size()&&nr.size()==nav.at("initialized_rows")&&nav.at("raw_rows")==n,"numeric print navigation denominator");std::vector<bool>seen(n);
 for(std::size_t k=0;k<nr.size();++k){const auto i=nr[k];need(i<n&&!seen[i],"duplicate numeric navigation row");seen[i]=true;auto&r=b.core.packet.rows[i];need(r.active&&r.kind==0&&b.core.model.materials.at(r.material).label.find(".print.")!=std::string::npos&&std::isfinite(ns[k])&&r.station_allowed(b.core.model,int(npath[k]),ns[k]),"invalid numeric print curve seed");if(r.source_finite_paths)need(std::find(r.source_finite_paths->begin(),r.source_finite_paths->end(),int(npath[k]))!=r.source_finite_paths->end(),"numeric seed enlarged the actual source curve");else need(joint_source_finite_path_allowed_v1(b.core.packet,b.core.model,i,int(npath[k])),"numeric seed enlarged a retained source curve");r.path=int(npath[k]);r.station=ns[k];b.core.station[i]=ns[k];}

 Json receipt={{"schema","rinkfit.native_source_shape_warm_restart_receipt.v1"},{"passed",true},{"source_state_token",cp.state.token()},{"old_physical_blocks",old_blocks.size()},{"new_physical_blocks",current.at("blocks").size()-old_blocks.size()},{"original_physical_values_and_domains_preserved",true},{"raw_rows",n},{"preserved_raw_nuisance_prefix",old},{"new_source_rows",n-old},{"restored_source_rows",restored},{"withheld_source_rows",withheld},{"original_source_UV_ID_PTS_operators_preserved",true},{"historical_shape_replay_disabled",true},{"shape_corrected_prefix_rows",changed_shape_rows},{"numerical_print_station_navigation_required",false},{"numeric_print_navigation_rows",nr.size()},{"numeric_print_navigation",manifest.at("print_numeric_navigation")},{"optimizer_history_restored",false},{"extras",extras},{"quality_accepted",false}};
 eventio::atomic_json(out/"native_repair_restart.json",receipt);return receipt;
}
